    const u = Math.max(this.prng(), 1e-12);
    const v = this.prng();
    return mean + std * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  }

  bool(pTrue: number): boolean {
    return this.prng() < pTrue;
  }
}

