import { readFileSync } from "node:fs";
import { join } from "node:path";
import { NextResponse } from "next/server";
import { confusionAt } from "../../../src/engine/metrics";
import { THRESHOLD } from "../../../src/engine/config";
import type { Claim, Label, ScoredClaim } from "../../../src/engine/types";

export const dynamic = "force-dynamic";

function read<T>(...parts: string[]): T {
  return JSON.parse(readFileSync(join(process.cwd(), ...parts), "utf8")) as T;
}

export function GET() {
  try {
    const claims = read<Claim[]>("data", "claims.json");
    const labels = read<Label[]>("data", "labels.json");
    const scored = read<ScoredClaim[]>("output", "scored_output.json");

    const claimById = new Map(claims.map((c) => [c.claim_id, c]));
    const labelById = new Map(labels.map((l) => [l.claim_id, l]));
    const labelMap = new Map(labels.map((l) => [l.claim_id, l]));

    const rows = scored.map((s) => ({
      ...s,
      claim: claimById.get(s.claim_id) ?? null,
      is_fraud: labelById.get(s.claim_id)?.is_fraud ?? false,
      fraud_patterns: labelById.get(s.claim_id)?.fraud_patterns ?? [],
    }));

    return NextResponse.json({
      threshold: THRESHOLD,
      metrics: confusionAt(scored, labelMap, THRESHOLD),
      claims: rows,
    });
  } catch {
    return NextResponse.json(
      { error: "Run `npm run generate` and `npm run score` first." },
      { status: 503 },
    );
  }
}

