  useEffect(() => {
    fetch("/api/claims")
      .then((r) => (r.ok ? r.json() : r.json().then((e) => Promise.reject(e.error))))
      .then(setData)
      .catch((e) => setError(String(e)));
  }, []);

  const rows = useMemo(() => {
    if (!data) return [];
    return onlyFlagged ? data.claims.filter((c) => c.risk_score >= data.threshold) : data.claims;
  }, [data, onlyFlagged]);

  if (error) return <main style={{ padding: 32 }}>{error}</main>;
  if (!data) return <main style={{ padding: 32 }}>Loading…</main>;

  const m = data.metrics;
  const card = { background: "#1e293b", borderRadius: 8, padding: "12px 16px", minWidth: 120 };

  return (
    <main style={{ padding: 32, maxWidth: 1100, margin: "0 auto" }}>
      <h1 style={{ marginBottom: 4 }}>Fraud Detection Scoring Engine</h1>
      <p style={{ color: "#94a3b8", marginTop: 0 }}>
        {data.claims.length} claims scored · flag threshold {data.threshold}
      </p>

      <div style={{ display: "flex", gap: 12, flexWrap: "wrap", margin: "16px 0 24px" }}>
        <div style={card}><div style={{ color: "#94a3b8", fontSize: 12 }}>Recall</div><div style={{ fontSize: 22 }}>{pct(m.recall)}</div></div>
        <div style={card}><div style={{ color: "#94a3b8", fontSize: 12 }}>False positive rate</div><div style={{ fontSize: 22 }}>{pct(m.fpr)}</div></div>
        <div style={card}><div style={{ color: "#94a3b8", fontSize: 12 }}>Precision</div><div style={{ fontSize: 22 }}>{pct(m.precision)}</div></div>
        <div style={card}><div style={{ color: "#94a3b8", fontSize: 12 }}>TP / FP / FN / TN</div><div style={{ fontSize: 22 }}>{m.tp} / {m.fp} / {m.fn} / {m.tn}</div></div>
      </div>

      <label style={{ display: "block", marginBottom: 12, color: "#94a3b8" }}>
        <input type="checkbox" checked={onlyFlagged} onChange={(e) => setOnlyFlagged(e.target.checked)} />{" "}
        show only flagged claims ({rows.length})
      </label>

      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 14 }}>
        <thead>
          <tr style={{ textAlign: "left", color: "#94a3b8" }}>
            <th style={{ padding: 8 }}>Claim</th>
            <th style={{ padding: 8 }}>Risk</th>
            <th style={{ padding: 8 }}>Flags</th>
            <th style={{ padding: 8 }}>Ground truth</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => (
            <>
              <tr
                key={r.claim_id}
                onClick={() => setOpen(open === r.claim_id ? null : r.claim_id)}
                style={{ cursor: "pointer", borderTop: "1px solid #334155" }}
              >
                <td style={{ padding: 8, fontFamily: "monospace" }}>{r.claim_id}</td>
                <td style={{ padding: 8 }}>
                  <span
                    style={{
                      background: r.risk_score >= 66 ? "#b91c1c" : r.risk_score >= data.threshold ? "#b45309" : "#334155",
                      borderRadius: 4,
                      padding: "2px 8px",
                    }}
                  >
                    {r.risk_score}
                  </span>
                </td>
                <td style={{ padding: 8 }}>{r.flags.map((f) => f.rule).join(", ") || "—"}</td>
                <td style={{ padding: 8, color: r.is_fraud ? "#f87171" : "#4ade80" }}>
                  {r.is_fraud ? `fraud (${r.fraud_patterns.join(", ")})` : "honest"}
                </td>
              </tr>
              {open === r.claim_id && (
                <tr key={`${r.claim_id}-d`} style={{ background: "#0b1220" }}>
                  <td colSpan={4} style={{ padding: 16 }}>
                    <pre style={{ margin: 0, whiteSpace: "pre-wrap", color: "#cbd5e1" }}>
                      {JSON.stringify(r.claim, null, 2)}
                    </pre>
                    <ul>
                      {r.flags.map((f, i) => (
                        <li key={i}>
                          <strong>{f.rule}</strong> (severity {f.severity}) — {f.evidence}
                        </li>
                      ))}
                    </ul>
                  </td>
                </tr>
              )}
            </>
          ))}
        </tbody>
      </table>
    </main>
  );
}

