import { UPCODING_MIN_SAMPLE, UPCODING_SD, WEIGHTS } from "../config";
import type { Rule } from "../types";

/**
 * Rule 3 — submitted amount > mean + 2·sd for the procedure code.
 *
 * submitted_amount is claim-level, so the per-procedure distribution attributes the
 * full claim amount to each code the claim contains (see aggregates.ts). A claim is
 * flagged on its worst-offending code.
 */
export const upcoding: Rule = {
  name: "upcoding",
  severity: WEIGHTS.upcoding,
  run(claim, ctx) {
    let worst: { code: string; z: number; mean: number; count: number } | null = null;

    for (const code of claim.procedure_codes) {
      const stat = ctx.agg.procedureStats.get(code);
      if (!stat || stat.count < UPCODING_MIN_SAMPLE || stat.std <= 0) continue;
      const z = (claim.submitted_amount - stat.mean) / stat.std;
      if (z > UPCODING_SD && (!worst || z > worst.z)) {
        worst = { code, z, mean: stat.mean, count: stat.count };
      }
